        stack=[(r,c)]; seen.add((r,c)); cl=[]
        while stack:
            rr,cc=stack.pop()
            cl.append((rr,cc,g[rr][cc]))
            for nr,nc in sorted(((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)), key=lambda x:x[0]+x[1]*100):
                if 0<=nr<len(g) and 0<=nc<len(g[0]) and g[nr][nc]!=bg and (nr,nc) not in seen:
